<?php
use EIPSI\StudyEngine\Persistence as P;
use EIPSI\StudyEngine\Privacy as G;
use EIPSI\StudyEngine\Contracts\Canonical;
function pg_race($input,$http=false){global $wpdb;$dir='/tmp/eipsi-p1g-race-'.bin2hex(random_bytes(6));mkdir($dir,0700);$input['clock']=$GLOBALS['pf_now'];file_put_contents($dir.'/input.json',json_encode($input));$processes=array();$result=array();$trigger='pg_hold_'.bin2hex(random_bytes(5));$lock='pg_lock_'.bin2hex(random_bytes(6));
 try{
  if($http){pe_assert((int)$wpdb->get_var($wpdb->prepare('SELECT GET_LOCK(%s,0)',$lock))===1,'No barrier');pe_assert($wpdb->query('CREATE TRIGGER `'.$trigger.'` BEFORE INSERT ON `'.$wpdb->prefix.'eipsi_engine_execution_commands` FOR EACH ROW BEGIN SET @pg_wait=GET_LOCK(\''.$lock.'\',15); SET @pg_release=RELEASE_LOCK(\''.$lock.'\'); END')!==false,'Trigger');}
  foreach(array(0,1) as $i){$pipes=array();$processes[$i]=proc_open(array(PHP_BINARY,__DIR__.'/race-worker.php',$dir,(string)$i),array(0=>array('pipe','r'),1=>array('file',$dir.'/stdout'.$i,'w'),2=>array('file',$dir.'/stderr'.$i,'w')),$pipes);pe_assert(is_resource($processes[$i]),'Spawn');fclose($pipes[0]);}
  foreach(array(0,1) as $i)pd_wait($dir.'/ready'.$i);touch($dir.'/start0');
  if($http){$end=microtime(true)+15;do{$waiting=(int)$wpdb->get_var("SELECT COUNT(*) FROM information_schema.PROCESSLIST WHERE STATE='User lock'");if($waiting)break;usleep(10000);}while(microtime(true)<$end);pe_assert($waiting>0,'HTTP did not acquire execution lock');}else pd_wait($dir.'/locked0');
  touch($dir.'/start1');pd_wait($dir.'/attempt1');usleep(100000);pe_assert(!file_exists($dir.'/result1.json'),'Second operation did not wait');
  if($http)$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));else touch($dir.'/release0');
  foreach(array(0,1) as $i){pd_wait($dir.'/result'.$i.'.json');$result[]=json_decode(file_get_contents($dir.'/result'.$i.'.json'),true);pe_assert(proc_close($processes[$i])===0,'Worker fatal');unset($processes[$i]);}return $result;
 }finally{if($http){$wpdb->get_var($wpdb->prepare('SELECT RELEASE_LOCK(%s)',$lock));$wpdb->query('DROP TRIGGER IF EXISTS `'.$trigger.'`');}touch($dir.'/release0');foreach($processes as $p){proc_terminate($p);proc_close($p);}foreach(glob($dir.'/*') as $p)unlink($p);rmdir($dir);}
}
foreach(array('withdraw','export') as $first)pg_case('real DB race B2 versus export first='.$first,function()use($first){$f=pg_complete(pf_enroll(pf_publish()));$s=pg_shell($f);$ops=array('withdraw'=>array('kind'=>'withdraw','hold'=>'before_withdrawal_commit'),'export'=>array('kind'=>'export','hold'=>'export_locked'));$second=$first==='withdraw'?'export':'withdraw';$r=pg_race(array('operations'=>array($ops[$first],$ops[$second]),'study'=>$f['study']['study_id'],'public'=>$f['study']['public_id'],'execution'=>$f['access']['execution_id'],'withdrawal_token'=>$s['token'],'revision'=>pg_row($f)['revision']));foreach($r as $v)pe_assert(!isset($v['error']),Canonical::json($v));$export=$r[$first==='export'?0:1];pe_assert($first==='export'?$export['rows']>0:$export['rows']===0,'Wrong materialization boundary');pe_assert(pg_export($f)['rows']===array(),'New export leak');});
foreach(array('submit','withdraw') as $first)pg_case('real DB submit versus withdrawal first='.$first,function()use($first){$p=pf_publish();$f=pf_enroll($p);$shell=pg_shell($f);$science=pe_request($f,'submit',array('R_q1'=>'race-value'),'RACE_SUBMIT_DOMAIN');$ops=array('submit'=>array('kind'=>'submit','request'=>$science,'token'=>$f['token'],'hold'=>'before_event_commit'),'withdraw'=>array('kind'=>'withdraw','hold'=>'before_withdrawal_commit','retry'=>true));$second=$first==='submit'?'withdraw':'submit';$r=pg_race(array('operations'=>array($ops[$first],$ops[$second]),'study'=>$f['study']['study_id'],'public'=>$p['public'],'execution'=>$f['access']['execution_id'],'withdrawal_token'=>$shell['token'],'revision'=>$shell['view']['revision']));foreach($r as $v)pe_assert(!isset($v['error']),Canonical::json($v));if($first==='submit')pe_assert(in_array($r[0]['status'],array(200,403),true)&&$r[1]['status']===200&&pg_row($f)['state']==='COMPLETED'&&pg_row($f)['data_policy']==='DO_NOT_USE'&&pg_count('submission_journal',$f)===1,'Submit-first hybrid: '.Canonical::json($r));else pe_assert($r[0]['status']===200&&$r[1]['status']===403&&pg_row($f)['state']==='WITHDRAWN'&&pg_count('submission_journal',$f)===0,'Withdraw-first hybrid: '.Canonical::json($r));});
